DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'users_session_id_fkey' AND conrelid = 'users'::regclass) THEN ALTER TABLE users ADD CONSTRAINT users_session_id_fkey FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE NOT VALID; END IF; END; $$;
